        return [c for c in p.split('/') if c not in ('', '.')]

    if path.startswith('/'):
        current = '/'
    else:
        current = cwd

    queue = split_components(path)
    count = 0

    while queue:
        comp = queue.pop(0)
        if comp == '..':
            if current == '/':
                pass
            else:
                idx = current.rfind('/')
                if idx <= 0:
                    current = '/'
                else:
                    current = current[:idx]
        else:
            if current == '/':
                newpath = '/' + comp
            else:
                newpath = current + '/' + comp

            if newpath in links:
                count += 1
                if count > 8:
                    return None
                target = links[newpath]
                if target.startswith('/'):
                    base = '/'
                else:
                    idx = newpath.rfind('/')
                    if idx <= 0:
                        base = '/'
                    else:
                        base = newpath[:idx]
                target_comps = split_components(target)
                # prepend target resolution using base as starting current
                current = base
                queue = target_comps + queue
            else:
                current = newpath

